import cv2
import numpy as np

import rclpy
from rclpy.node import Node

from sensor_msgs.msg import Image
from geometry_msgs.msg import Twist
from cv_bridge import CvBridge


class RoadBoundaryFollower(Node):
    def __init__(self):
        super().__init__('road_boundary_follower')

        self.bridge = CvBridge()

        self.image_sub = self.create_subscription(
            Image,
            '/camera/image_raw',
            self.image_callback,
            10
        )

        self.cmd_pub = self.create_publisher(Twist, '/cmd_vel', 10)

        # 제어 파라미터
        self.kp = 0.0040
        self.kd = 0.0020
        self.linear_speed = 0.08
        self.max_angular = 0.5

        self.prev_error = 0.0
        self.prev_center = None

        # ROI
        self.roi_start_ratio = 0.40
        self.roi_end_ration = 0.88
        self.roi_side_margin_ratio = 0.08

        # ROI 아래쪽 차량 보닛 제거 비율
        self.cut_bottom_ratio = 0.18
        
        # scanline
        self.scanline_ratios = [0.30, 0.45, 0.60, 0.75]
        self.scanline_weights = [1.5, 2.0, 2.5, 3.0]

        # HSV (갈색 road 기준)
        self.lower_hsv = np.array([8, 120, 90], dtype=np.uint8)
        self.upper_hsv = np.array([20, 255, 190], dtype=np.uint8)

        self.kernel = np.ones((5, 5), np.uint8)

        # 한쪽 경계만 보일 때 사용할 추정 도로폭
        self.estimated_road_width_px = 220

        self.get_logger().info('road_boundary_follower node started')

    def image_callback(self, msg):
        frame = self.bridge.imgmsg_to_cv2(msg, desired_encoding='bgr8')
        height, width = frame.shape[:2]

        roi_y = int(height * self.roi_start_ratio)
        x0 = int(width * self.roi_side_margin_ratio)
        x1 = int(width * (1.0 - self.roi_side_margin_ratio))

        roi = frame[roi_y:height, x0:x1].copy()
        roi_h, roi_w = roi.shape[:2]
        
        # 아래쪽 보닛 제거
        cut_bottom = int(roi_h * self.cut_bottom_ratio)
        if cut_bottom > 0:
            roi = roi[:roi_h - cut_bottom, :]
        roi_h, roi_w = roi.shape[:2]

        hsv = cv2.cvtColor(roi, cv2.COLOR_BGR2HSV)
        mask = cv2.inRange(hsv, self.lower_hsv, self.upper_hsv)

        mask = cv2.morphologyEx(mask, cv2.MORPH_OPEN, self.kernel)
        mask = cv2.morphologyEx(mask, cv2.MORPH_CLOSE, self.kernel)

        # 좌우 끝에 붙는 과검출 방지
        edge_margin = int(roi_w * 0.03)
        mask[:, :edge_margin] = 0
        mask[:, roi_w - edge_margin:] = 0
        
        mask = self.keep_largest_component(mask)
        mask_pixels = int(np.count_nonzero(mask))
        vis = roi.copy()
    
        centers = []
        left_points = []
        right_points = []

        for ratio, weight in zip(self.scanline_ratios, self.scanline_weights):
            y = int(roi_h * ratio)
            y = int(np.clip(y, 0, roi_h - 1))

            cv2.line(vis, (0, y), (roi_w - 1, y), (80, 80, 80), 1)

            row = mask[y, :]
            xs = np.where(row > 0)[0]

            if len(xs) < 20:
                continue

            left_x = int(xs[0])
            right_x = int(xs[-1])

            left_visible = left_x > 2
            right_visible = right_x < roi_w - 3

            center_x = None

            # 1) 양쪽 경계 모두 보이는 경우
            if left_visible and right_visible:
                road_width = right_x - left_x
                if road_width >= 30:
                    center_x = (left_x + right_x) / 2.0
                    left_points.append((left_x, y))
                    right_points.append((right_x, y))

                    # 도로폭 추정값 업데이트
                    self.estimated_road_width_px = int(
                        0.9 * self.estimated_road_width_px + 0.10 * road_width
                    )

            # 2) 왼쪽 경계만 보이는 경우
            elif left_visible and not right_visible:
                center_x = left_x + self.estimated_road_width_px / 2.0
                center_x = min(center_x, roi_w - 1)
                left_points.append((left_x, y))

            # 3) 오른쪽 경계만 보이는 경우
            elif not left_visible and right_visible:
                center_x = right_x - self.estimated_road_width_px / 2.0
                center_x = max(center_x, 0)
                right_points.append((right_x, y))

            if center_x is not None:
                centers.append((center_x, weight, y))

        lane_center = None

        if len(centers) >= 2:
            weighted_sum = sum(c * w for c, w, _ in centers)
            weight_total = sum(w for _, w, _ in centers)
            lane_center = weighted_sum / weight_total
            self.prev_center = lane_center

        elif len(centers) == 1:
            lane_center = centers[0][0]
            self.prev_center = lane_center

        elif self.prev_center is not None:
            lane_center = self.prev_center

        for x, y in left_points:
            cv2.circle(vis, (x, y), 4, (255, 0, 0), -1)

        for x, y in right_points:
            cv2.circle(vis, (x, y), 4, (0, 0, 255), -1)

        image_center = roi_w / 2.0
        cv2.line(vis, (int(image_center), 0), (int(image_center), roi_h - 1), (0, 255, 255), 2)

        if lane_center is not None:
            cv2.line(vis, (int(lane_center), 0), (int(lane_center), roi_h - 1), (0, 255, 0), 2)

        twist = Twist()

        if lane_center is not None:
            error = lane_center - image_center
            derivative = error - self.prev_error

            control = self.kp * error + self.kd * derivative
            control = float(np.clip(control, -self.max_angular, self.max_angular))

            self.prev_error = error

            twist.linear.x = self.linear_speed
            twist.angular.z = -control

            cv2.putText(
                vis,
                f'error={error:.1f} control={control:.3f} est_w={self.estimated_road_width_px}',
                (20, 30),
                cv2.FONT_HERSHEY_SIMPLEX,
                0.7,
                (255, 255, 255),
                2
            )
        else:
            twist.linear.x = 0.0
            twist.angular.z = 0.0

            cv2.putText(
                vis,
                'boundary not found',
                (20, 30),
                cv2.FONT_HERSHEY_SIMPLEX,
                0.8,
                (0, 0, 255),
                2
            )

        self.cmd_pub.publish(twist)

        frame_vis = frame.copy()
        cv2.rectangle(frame_vis, (x0, roi_y), (x1, height - 1), (0, 0, 255), 2)

        mask_vis = cv2.cvtColor(mask, cv2.COLOR_GRAY2BGR)

        cv2.imshow('camera_with_roi', frame_vis)
        cv2.imshow('road_boundary_follow', vis)
        cv2.imshow('road_mask', mask_vis)
        cv2.waitKey(1)

    def keep_largest_component(self, mask):
        num_labels, labels, stats, _ = cv2.connectedComponentsWithStats(
            mask,
            connectivity=8
        )

        if num_labels <= 1:
            return np.zeros_like(mask)

        largest_label = -1
        largest_area = 0

        for i in range(1, num_labels):
            area = stats[i, cv2.CC_STAT_AREA]
            if area > largest_area:
                largest_area = area
                largest_label = i

        output = np.zeros_like(mask)
        if largest_label != -1:
            output[labels == largest_label] = 255

        return output


def main(args=None):
    rclpy.init(args=args)
    node = RoadBoundaryFollower()

    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        stop_msg = Twist()
        node.cmd_pub.publish(stop_msg)
        cv2.destroyAllWindows()
        node.destroy_node()
        rclpy.shutdown()


if __name__ == '__main__':
    main()
